import{_ as i,o as a,c as t,a3 as s}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Styling entity images","description":"Learn all about styling entity images.","frontmatter":{"description":"Learn all about styling entity images."},"headers":[],"relativePath":"en/projects/uix/using/images.md","filePath":"en/projects/uix/using/images.md","lastUpdated":1793108161000}'),n={name:"en/projects/uix/using/images.md"};function r(o,e,l,c,d,p){return a(),t("div",null,[...e[0]||(e[0]=[s(`<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>dev</code> / <strong>9.0.0-beta.2</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/26e54e6d4973231a393933e6479ed1b03cc86cd3" target="_blank" rel="noreferrer">26e54e6</a>, reviewed 22 October 2026. This source mirror may describe preview behavior beyond stable 8.4.0. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><h1 id="styling-entity-images" tabindex="-1">Styling entity images <a class="header-anchor" href="#styling-entity-images" aria-label="Permalink to &quot;Styling entity images&quot;">​</a></h1><p>UIX can substitute the background entity image displayed by the following elements:</p><ul><li><code>ha-entity-marker</code> (map card entity markers)</li><li><code>ha-tile-icon</code> (tile card icons)</li><li><code>state-badge</code> (state badges)</li><li><code>ha-user-badge</code> (user badges)</li><li><code>ha-person-badge</code> (person badges)</li><li><code>hui-entity-badge</code> (entity badge)</li><li><code>hui-map-overview</code> (map dashboard overview people and devices)</li></ul><p>Styling can be via <a href="#specifying-for-an-entity-override">specifying for an entity override</a> or a <a href="#specifying-generic-override">generic override</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>When styling entity image for an entity badge (<code>hui-entity-badge</code>), you must set <strong>Show entity picture</strong> (<code>show_entity_picture: true</code> in YAML).</p></div><h2 id="specifying-for-an-entity-override" tabindex="-1">Specifying for an entity override <a class="header-anchor" href="#specifying-for-an-entity-override" aria-label="Permalink to &quot;Specifying for an entity override&quot;">​</a></h2><p>Define a CSS variable of the form <code>--uix-image-for-&lt;entity_id&gt;</code>, where every <code>.</code> in the entity ID is replaced with <code>_</code>. When an element is rendered for the matching entity, the background image is replaced with the supplied URL.</p><p>Templates are supported.</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tile</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">entity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">person.jim</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">uix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    :host {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      --uix-image-for-person_jim: /local/photos/jim.jpg;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>The variable can be set at any ancestor level in the DOM. UIX will detect it on the element via computed styles. If the variable is not set, or the element&#39;s entity does not match, the original image is left unchanged.</li><li>To style an override across Home Assistant Frontend add <code>--uix-image-for-&lt;entity_id&gt;</code> to theme variables <code>uix-root(-yaml)</code>, <code>uix-config(-yaml)</code> and <code>uix-more-info(-yaml)</code>.</li><li>Map dashboard overview images support entity-specific overrides only; <code>--uix-image</code> does not apply there.</li></ul></div><h2 id="specifying-generic-override" tabindex="-1">Specifying generic override <a class="header-anchor" href="#specifying-generic-override" aria-label="Permalink to &quot;Specifying generic override&quot;">​</a></h2><p>Define a generic CSS variable <code>--uix-image</code> in the context of the image you wish to override, for example on an element containing <code>ha-entity-marker</code> (e.g. map), <code>ha-tile-icon</code> (e.g. tile card), or <code>state-badge</code> (e.g. entities row).</p><p>When a supported element is rendered within that context, the background image is replaced with the supplied URL regardless of entity ID.</p><p>Templates are supported.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If both <code>--uix-image</code> and <code>--uix-image-for-&lt;entity_id&gt;</code> are defined, <code>--uix-image</code> takes precedence.</p></div>`,16)])])}const m=i(n,[["render",r]]);export{g as __pageData,m as default};
